(()=>{
 const content=document.querySelector('#databaseContent'),message=document.querySelector('#databaseStatus'),next=document.querySelector('#databaseNext'),previous=document.querySelector('#databasePrevious'),select=document.querySelector('#databaseTable');let mode='accounts',offset=0,nextOffset=null,request=0;
 async function load(){const version=++request;content.replaceChildren();message.textContent='Loading…';next.disabled=previous.disabled=true;try{if(mode==='tables'&&!select.options.length){const tables=await get('/api/admin/tables');if(version!==request)return;for(const table of tables){const option=document.createElement('option');option.value=table;option.textContent=table.replaceAll('_',' ');select.append(option);}}const result=await get(mode==='accounts'?`/api/admin/accounts?offset=${offset}`:`/api/admin/tables/${encodeURIComponent(select.value)}?offset=${offset}`);if(version!==request)return;
 const rows=mode==='accounts'?result.accounts:result.rows;for(const row of rows){const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');if(mode==='accounts'){summary.textContent=(row.preferences?.display_name||row.identities[0]?.display_name||'Unnamed account')+' · '+row.id;pre.textContent=JSON.stringify(row,null,2);}else{let value;try{value=JSON.parse(row.data);}catch{value=null;}summary.textContent=value?Object.entries(value).slice(0,3).map(([key,val])=>`${key}: ${typeof val==='object'?'…':val}`).join(' · '):'Record (truncated)';pre.textContent=value?JSON.stringify(value,null,2):row.data;if(row.truncated)pre.textContent+='\n[Record exceeds 16 KiB; display truncated]';}details.append(summary,pre);content.append(details);}
 nextOffset=result.nextOffset;previous.disabled=offset===0;next.disabled=nextOffset===null;message.textContent=rows.length?`Showing ${offset+1}–${offset+rows.length}. Read-only.`:'No records found.';
 }catch(error){if(version===request){content.replaceChildren();message.textContent=error.message;}}}
 document.querySelectorAll('[data-db-view]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.dbView;offset=0;select.hidden=mode==='accounts';document.querySelectorAll('[data-db-view]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));load();}));
 select.addEventListener('change',()=>{offset=0;load();});next.addEventListener('click',()=>{offset=nextOffset;load();});previous.addEventListener('click',()=>{offset=Math.max(0,offset-50);load();});document.querySelector('#databaseRefresh').addEventListener('click',load);
 load();})();
